export const timelineYears = [2014, 2015, 2016, 2017, 2018, 2019, 2020, 2021, 2022, 2023];

export const getAviationDataForYear = (year) => {
  const yearIndex = timelineYears.indexOf(year);
  const dataList = [];
  
  for (const [id, country] of Object.entries(rawAviationData)) {
    const yearData = country.data[yearIndex];
    
    if (yearData) {
      const currentEmissions = yearData[2] + yearData[3];
      let change = 0;

      // Calcular la variación respecto al año anterior (exactamente como tu Excel)
      if (yearIndex > 0) {
        const prevYearData = country.data[yearIndex - 1];
        if (prevYearData) {
          const prevEmissions = prevYearData[2] + prevYearData[3];
          change = prevEmissions !== 0 ? ((currentEmissions - prevEmissions) / prevEmissions) * 100 : 0;
        }
      }

      dataList.push({
        id,
        name: country.name,
        pax: yearData[0],
        mainAirports: yearData[1],
        domestic: yearData[2],
        international: yearData[3],
        emissions: parseFloat(currentEmissions.toFixed(1)),
        change: parseFloat(change.toFixed(2)) // Variación real año a año
      });
    }
  }
  return dataList;
};

