export const interpolateColor = (color1, color2, factor) => {
  const hex = (c) => parseInt(c.slice(1), 16);
  const r1 = hex(color1) >> 16, g1 = (hex(color1) >> 8) & 0xff, b1 = hex(color1) & 0xff;
  const r2 = hex(color2) >> 16, g2 = (hex(color2) >> 8) & 0xff, b2 = hex(color2) & 0xff;
  
  
  const safeFactor = Math.max(0, Math.min(1, factor || 0));
  
  const r = Math.round(r1 + safeFactor * (r2 - r1));
  const g = Math.round(g1 + safeFactor * (g2 - g1));
  const b = Math.round(b1 + safeFactor * (b2 - b1));
  
  
  return `#${(1 << 24 | r << 16 | g << 8 | b).toString(16).slice(1)}`;
};